content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: #e0e7ff;
  --secondary-color: #64748b;
  --secondary-hover: #475569;
  --success-color: #10b981;
  --miss-color: #ef4444;
  --bg-gradient: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #0f172a 100%);
  --card-bg: rgba(30, 41, 59, 0.85);
  --card-border: rgba(255, 255, 255, 0.1);
  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;
  --typed-color: #38bdf8;
  --current-color: #fbbf24;
  --remaining-color: #94a3b8;
  --radius-lg: 16px;
  --radius-md: 10px;
  --radius-sm: 6px;
  --shadow-main: 0 20px 30px -10px rgba(0, 0, 0, 0.5);
  --font-family: 'Helvetica Neue', Arial, 'Hiragino Kaku Gothic ProN', 'Hiragino Sans', Meiryo, sans-serif;
  --font-mono: 'Consolas', 'Courier New', 'Courier', monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  margin: 0;
  font-family: var(--font-family);
  background: var(--bg-gradient);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

/* アプリ全体のコンテナ */
.app-container {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: relative;
}

/* ヘッダーエリア */
.header {
  text-align: center;
  padding: 8px 0;
}

.header h1 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(to right, #60a5fa, #a78bfa, #f472b6);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  margin-bottom: 6px;
}

.header p {
  font-size: 0.95rem;
  color: var(--text-secondary);
}

/* ゲームカード（メイン表示枠） */
.game-card {
  background: var(--card-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-main);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease;
}

/* 統計情報バー */
.stats-bar {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  margin-bottom: 24px;
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: #38bdf8;
  font-family: var(--font-mono);
  line-height: 1.2;
}

.stat-label {
  font-size: 0.75rem;
  color: var(--text-secondary);
  margin-top: 4px;
  font-weight: 500;
}

/* タイマープログレスバー */
.timer-progress {
  width: 100%;
  height: 8px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 9999px;
  overflow: hidden;
  margin-bottom: 24px;
}

.timer-bar {
  height: 100%;
  background: linear-gradient(90deg, #38bdf8, #818cf8);
  border-radius: 9999px;
  transition: width 0.2s linear;
}

/* タイピング表示エリア */
.word-display-area {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 180px;
  padding: 24px 16px;
  border-radius: var(--radius-md);
  background: rgba(15, 23, 42, 0.4);
  border: 1px dashed rgba(255, 255, 255, 0.15);
  cursor: pointer;
  position: relative;
  user-select: none;
}

.word-kana {
  font-size: 1.1rem;
  color: #a5b4fc;
  margin-bottom: 4px;
  font-weight: 500;
  letter-spacing: 0.05em;
}

.word-kanji {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--text-primary);
  margin-bottom: 16px;
  letter-spacing: 0.04em;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.4);
}

.romaji-display {
  font-family: var(--font-mono);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
}

.romaji-typed {
  color: var(--typed-color);
  opacity: 0.85;
}

.romaji-current {
  color: var(--current-color);
  border-bottom: 3px solid var(--current-color);
  animation: cursorBlink 1s infinite;
  background: rgba(251, 191, 36, 0.1);
  border-radius: 2px 2px 0 0;
  padding: 0 1px;
}

.romaji-remaining {
  color: var(--remaining-color);
  opacity: 0.55;
}

/* ミス時のシェイクアニメーション */
.shake-miss {
  animation: shake 0.28s cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@keyframes shake {
  10%, 90% {
    transform: translate3d(-2px, 0, 0);
  }
  20%, 80% {
    transform: translate3d(3px, 0, 0);
  }
  30%, 50%, 70% {
    transform: translate3d(-5px, 0, 0);
  }
  40%, 60% {
    transform: translate3d(5px, 0, 0);
  }
}

@keyframes cursorBlink {
  0%, 100% {
    border-bottom-color: var(--current-color);
  }
  50% {
    border-bottom-color: transparent;
  }
}

/* スマホ用キーボード表示用の不可視インプット */
.hidden-input {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
  z-index: 5;
}

.mobile-hint {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-top: 12px;
  display: block;
}

/* スタート画面・ガイド */
.start-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 36px 16px;
  gap: 20px;
}

.guide-text {
  color: var(--text-secondary);
  font-size: 1rem;
  line-height: 1.6;
  max-width: 480px;
}

/* 共通ボタンスタイル */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  padding: 12px 28px;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
  text-decoration: none;
  gap: 8px;
}

.btn-primary {
  background: linear-gradient(135deg, #4f46e5, #6366f1);
  color: #ffffff;
  box-shadow: 0 4px 14px 0 rgba(79, 70, 229, 0.4);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #4338ca, #4f46e5);
  box-shadow: 0 6px 20px 0 rgba(79, 70, 229, 0.6);
  transform: translateY(-1px);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.1);
  color: var(--text-primary);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.18);
  transform: translateY(-1px);
}

/* 結果表示モーダル */
.result-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 100;
  animation: fadeIn 0.25s ease-out;
}

.result-card {
  background: #1e293b;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: var(--radius-lg);
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.7);
  padding: 32px 28px;
  width: 100%;
  max-width: 480px;
  text-align: center;
  animation: scaleUp 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.result-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 20px;
  color: var(--text-primary);
}

.result-score-highlight {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 3.5rem;
  font-weight: 900;
  width: 90px;
  height: 90px;
  border-radius: 50%;
  margin-bottom: 12px;
  background: linear-gradient(135deg, #f59e0b, #fbbf24);
  color: #1e1b4b;
  box-shadow: 0 0 25px rgba(245, 158, 11, 0.4);
}

.result-stats-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 28px;
}

.result-stat-box {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius-md);
  padding: 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.result-stat-box .stat-value {
  font-size: 1.4rem;
  color: #38bdf8;
}

.result-stat-box .stat-label {
  font-size: 0.8rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes scaleUp {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* レスポンシブ対応 (スマートフォン向け) */
@media (max-width: 600px) {
  .game-card {
    padding: 20px 16px;
  }

  .stats-bar {
    gap: 8px;
    padding: 10px 8px;
  }

  .stat-value {
    font-size: 1.25rem;
  }

  .stat-label {
    font-size: 0.7rem;
  }

  .word-kanji {
    font-size: 1.75rem;
    margin-bottom: 12px;
  }

  .word-kana {
    font-size: 0.95rem;
  }

  .romaji-display {
    font-size: 1.35rem;
  }

  .word-display-area {
    min-height: 150px;
    padding: 16px 12px;
  }

  .btn {
    width: 100%;
    padding: 12px 20px;
  }

  .result-card {
    padding: 24px 18px;
  }

  .rank-badge {
    font-size: 3rem;
    width: 80px;
    height: 80px;
  }
}

import type { ChangeEvent, RefObject } from 'react';

export interface TypingWord {
  id: number;
  kanji: string;
  kana: string;
  romaji: string;
}

export interface GameState {
  status: 'ready' | 'playing' | 'finished';
  timeLeft: number;
  correctChars: number;
  totalChars: number;
  missCount: number;
  currentWordIndex: number;
  currentCharIndex: number;
}

export interface GameResult {
  totalChars: number;
  correctChars: number;
  missCount: number;
  accuracy: number;
  wpm: number;
  rank: string;
}

export interface TypingDisplayProps {
  currentWord: TypingWord;
  charIndex: number;
  inputRef: RefObject<HTMLInputElement>;
  onInput: (e: ChangeEvent<HTMLInputElement>) => void;
  inputValue: string;
  isMissed: boolean;
}

export interface ResultModalProps {
  result: GameResult;
  onRestart: () => void;
}

import { type ChangeEvent, type RefObject, useEffect } from 'react';
import type { TypingDisplayProps } from '../types';

export default function TypingDisplay({
  currentWord,
  charIndex,
  inputRef,
  onInput,
  inputValue,
  isMissed
}: TypingDisplayProps) {
  const handleClickArea = () => {
    inputRef?.current?.focus();
  };

  useEffect(() => {
    inputRef?.current?.focus();
  }, [inputRef]);

  const romaji = currentWord?.romaji || '';
  const typedPart = romaji.slice(0, charIndex);
  const currentChar = romaji.charAt(charIndex);
  const remainingPart = romaji.slice(charIndex + 1);

  const containerClassName = isMissed
    ? 'word-display-area shake-miss'
    : 'word-display-area';

  return (
    <div className={containerClassName} onClick={handleClickArea} role="presentation">
      <input
        ref={inputRef}
        type="text"
        className="hidden-input"
        value={inputValue}
        onChange={onInput}
        autoFocus
        autoCapitalize="none"
        autoComplete="off"
        autoCorrect="off"
        spellCheck={false}
        aria-label="タイピング入力フィールド"
      />

      <div className="word-kana">{currentWord?.kana}</div>
      <div className="word-kanji">{currentWord?.kanji}</div>

      <div className="romaji-display">
        <span className="romaji-typed">{typedPart}</span>
        {currentChar && <span className="romaji-current">{currentChar}</span>}
        <span className="romaji-remaining">{remainingPart}</span>
      </div>

      <span className="mobile-hint">
        ※ 枠内をタップするとキーボードが開きます
      </span>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback, type ChangeEvent } from 'react';
import type { GameState, GameResult, TypingWord } from './types';
import { WORD_LIST } from './words';
import TypingDisplay from './components/TypingDisplay';
import ResultModal from './components/ResultModal';

const GAME_DURATION = 60;

export default function App() {
  const [gameState, setGameState] = useState<GameState>({
    status: 'ready',
    timeLeft: GAME_DURATION,
    correctChars: 0,
    totalChars: 0,
    missCount: 0,
    currentWordIndex: 0,
    currentCharIndex: 0
  });

  const [words, setWords] = useState<TypingWord[]>([]);
  const [inputValue, setInputValue] = useState<string>('');
  const [isMissed, setIsMissed] = useState<boolean>(false);
  const [finalResult, setFinalResult] = useState<GameResult | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);

  // オーディオコンテキストの初期化
  const getAudioContext = useCallback(() => {
    if (!audioContextRef.current) {
      const AudioCtx = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      if (AudioCtx) {
        audioContextRef.current = new AudioCtx();
      }
    }
    if (audioContextRef.current && audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    return audioContextRef.current;
  }, []);

  // Web Audio API による効果音生成
  const playSound = useCallback((type: 'correct' | 'miss' | 'complete' | 'finish') => {
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);

      const now = ctx.currentTime;

      if (type === 'correct') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(800, now);
        osc.frequency.exponentialRampToValueAtTime(1200, now + 0.05);
        gain.gain.setValueAtTime(0.12, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);
        osc.start(now);
        osc.stop(now + 0.06);
      } else if (type === 'miss') {
        osc.type = 'sawtooth';
        osc.frequency.setValueAtTime(220, now);
        osc.frequency.setValueAtTime(180, now + 0.06);
        gain.gain.setValueAtTime(0.18, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
        osc.start(now);
        osc.stop(now + 0.14);
      } else if (type === 'complete') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(523.25, now); // C5
        osc.frequency.setValueAtTime(659.25, now + 0.08); // E5
        osc.frequency.setValueAtTime(783.99, now + 0.16); // G5
        gain.gain.setValueAtTime(0.15, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);
        osc.start(now);
        osc.stop(now + 0.25);
      } else if (type === 'finish') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(440, now);
        osc.frequency.setValueAtTime(880, now + 0.12);
        gain.gain.setValueAtTime(0.2, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.4);
        osc.start(now);
        osc.stop(now + 0.4);
      }
    } catch {
      // オーディオエラーは無視
    }
  }, [getAudioContext]);

  // ワードリストをシャッフル
  const shuffleWords = useCallback(() => {
    const list = [...WORD_LIST];
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  }, []);

  // ランクの計算
  const calculateRank = (correct: number, accuracy: number): string => {
    if (correct >= 320 && accuracy >= 95) return 'S';
    if (correct >= 250 && accuracy >= 90) return 'A';
    if (correct >= 180 && accuracy >= 85) return 'B';
    if (correct >= 120) return 'C';
    return 'D';
  };

  // ゲーム終了処理
  const handleGameFinish = useCallback((state: GameState) => {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    playSound('finish');

    const accuracy = state.totalChars > 0
      ? (state.correctChars / state.totalChars) * 100
      : 0;

    const elapsedMinutes = (GAME_DURATION - state.timeLeft) / 60 || 1;
    const wpm = Math.round((state.correctChars / 5) / elapsedMinutes);
    const rank = calculateRank(state.correctChars, accuracy);

    const result: GameResult = {
      totalChars: state.totalChars,
      correctChars: state.correctChars,
      missCount: state.missCount,
      accuracy: Math.min(100, Math.max(0, accuracy)),
      wpm,
      rank
    };

    setFinalResult(result);
    setGameState(prev => ({
      ...prev,
      status: 'finished'
    }));
  }, [playSound]);

  // ゲームスタート
  const startGame = () => {
    getAudioContext();
    const shuffled = shuffleWords();
    setWords(shuffled);
    setInputValue('');
    setIsMissed(false);
    setFinalResult(null);

    setGameState({
      status: 'playing',
      timeLeft: GAME_DURATION,
      correctChars: 0,
      totalChars: 0,
      missCount: 0,
      currentWordIndex: 0,
      currentCharIndex: 0
    });

    setTimeout(() => {
      inputRef.current?.focus();
    }, 50);
  };

  // タイマー進行処理
  useEffect(() => {
    if (gameState.status === 'playing') {
      timerRef.current = window.setInterval(() => {
        setGameState(prev => {
          if (prev.timeLeft <= 1) {
            handleGameFinish({ ...prev, timeLeft: 0 });
            return { ...prev, timeLeft: 0 };
          }
          return { ...prev, timeLeft: prev.timeLeft - 1 };
        });
      }, 1000);
    }

    return () => {
      if (timerRef.current !== null) {
        clearInterval(timerRef.current);
      }
    };
  }, [gameState.status, handleGameFinish]);

  // 入力受付ハンドラー
  const handleInput = (e: ChangeEvent<HTMLInputElement>) => {
    if (gameState.status !== 'playing') return;

    const val = e.target.value;
    if (!val) {
      setInputValue('');
      return;
    }

    const typedChar = val.slice(-1).toLowerCase();
    setInputValue('');

    const currentWord = words[gameState.currentWordIndex] || WORD_LIST[0];
    const expectedChar = currentWord.romaji.charAt(gameState.currentCharIndex).toLowerCase();

    if (typedChar === expectedChar) {
      // 正解
      setIsMissed(false);
      const nextCharIndex = gameState.currentCharIndex + 1;
      const isWordCompleted = nextCharIndex >= currentWord.romaji.length;

      if (isWordCompleted) {
        playSound('complete');
        setGameState(prev => ({
          ...prev,
          correctChars: prev.correctChars + 1,
          totalChars: prev.totalChars + 1,
          currentWordIndex: (prev.currentWordIndex + 1) % words.length,
          currentCharIndex: 0
        }));
      } else {
        playSound('correct');
        setGameState(prev => ({
          ...prev,
          correctChars: prev.correctChars + 1,
          totalChars: prev.totalChars + 1,
          currentCharIndex: nextCharIndex
        }));
      }
    } else {
      // ミス
      playSound('miss');
      setIsMissed(true);
      setTimeout(() => setIsMissed(false), 280);

      setGameState(prev => ({
        ...prev,
        missCount: prev.missCount + 1,
        totalChars: prev.totalChars + 1
      }));
    }
  };

  // キーボード直接入力（PCブラウザ用）
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameState.status !== 'playing') {
        if (e.key === 'Enter' && (gameState.status === 'ready' || gameState.status === 'finished')) {
          e.preventDefault();
          startGame();
        }
        return;
      }

      // 制御キーはスキップ
      if (e.key.length !== 1 || e.ctrlKey || e.metaKey || e.altKey) {
        return;
      }

      const typedChar = e.key.toLowerCase();
      const currentWord = words[gameState.currentWordIndex] || WORD_LIST[0];
      const expectedChar = currentWord.romaji.charAt(gameState.currentCharIndex).toLowerCase();

      if (typedChar === expectedChar) {
        setIsMissed(false);
        const nextCharIndex = gameState.currentCharIndex + 1;
        const isWordCompleted = nextCharIndex >= currentWord.romaji.length;

        if (isWordCompleted) {
          playSound('complete');
          setGameState(prev => ({
            ...prev,
            correctChars: prev.correctChars + 1,
            totalChars: prev.totalChars + 1,
            currentWordIndex: (prev.currentWordIndex + 1) % words.length,
            currentCharIndex: 0
          }));
        } else {
          playSound('correct');
          setGameState(prev => ({
            ...prev,
            correctChars: prev.correctChars + 1,
            totalChars: prev.totalChars + 1,
            currentCharIndex: nextCharIndex
          }));
        }
      } else {
        playSound('miss');
        setIsMissed(true);
        setTimeout(() => setIsMissed(false), 280);

        setGameState(prev => ({
          ...prev,
          missCount: prev.missCount + 1,
          totalChars: prev.totalChars + 1
        }));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [gameState.status, gameState.currentWordIndex, gameState.currentCharIndex, words, playSound]);

  // リアルタイム正確率
  const currentAccuracy = gameState.totalChars > 0
    ? ((gameState.correctChars / gameState.totalChars) * 100).toFixed(0)
    : '100';

  // リアルタイムWPM
  const timeElapsed = GAME_DURATION - gameState.timeLeft;
  const currentWpm = timeElapsed > 0
    ? Math.round((gameState.correctChars / 5) / (timeElapsed / 60))
    : 0;

  // 制限時間の残り割合 (0% - 100%)
  const timerPercentage = (gameState.timeLeft / GAME_DURATION) * 100;
  const currentWord = words[gameState.currentWordIndex] || WORD_LIST[0];

  return (
    <div className="app-container">
      <header className="header">
        <h1>ローマ字タイピングマスター</h1>
        <p>60秒間で正確に素早くキーボードを入力しよう！</p>
      </header>

      <main className="game-card">
        {/* リアルタイムステータスバー */}
        <div className="stats-bar">
          <div className="stat-item">
            <span className="stat-value">{gameState.timeLeft}s</span>
            <span className="stat-label">残り時間</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">{gameState.correctChars}</span>
            <span className="stat-label">打鍵数</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">{currentWpm}</span>
            <span className="stat-label">WPM</span>
          </div>
          <div className="stat-item">
            <span className="stat-value">{currentAccuracy}%</span>
            <span className="stat-label">正確率</span>
          </div>
        </div>

        {/* タイムプログレスバー */}
        <div className="timer-progress">
          <div
            className="timer-bar"
            style={{ width: `${timerPercentage}%` }}
          />
        </div>

        {gameState.status === 'playing' ? (
          <TypingDisplay
            currentWord={currentWord}
            charIndex={gameState.currentCharIndex}
            inputRef={inputRef}
            onInput={handleInput}
            inputValue={inputValue}
            isMissed={isMissed}
          />
        ) : (
          <div className="start-screen">
            <p className="guide-text">
              表示される日本語とローマ字に合わせてキーボードを打ってください。
              <br />
              スマートフォンの方は画面をタップするとキーボードが立ち上がります。
            </p>
            <button
              type="button"
              className="btn btn-primary"
              onClick={startGame}
            >
              ゲームスタート (60秒)
            </button>
          </div>
        )}
      </main>

      {/* 終了後の結果発表モーダル */}
      {gameState.status === 'finished' && finalResult && (
        <ResultModal
          result={finalResult}
          onRestart={startGame}
        />
      )}
    </div>
  );
}
